from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

import config
import test_uniclubs_importer as source_fixtures
import test_uniclubs_sync as sync_fixtures
import uniclubs_database
import uniclubs_refresh


NOW = datetime(2026, 11, 15, 17, 0, tzinfo=timezone.utc)
NEXT = NOW + timedelta(hours=1)
FETCH_TARGET = 'uniclubs_importer.importers.fetch_uniclubs_sync_documents'


class UniClubsRefreshTests(unittest.TestCase):
    """Run the real JSON/SQLite pipeline with temporary files and mocked public transport."""

    def setUp(self):
        """Create an in-memory catalog and an isolated public JSON destination."""
        self.connection = self.catalog()
        directory = tempfile.TemporaryDirectory()
        self.addCleanup(directory.cleanup)
        self.path = Path(directory.name) / 'public' / 'uniclubs_events.json'
        self.item = source_fixtures.source_event()

    def catalog(self):
        """Return a new independent catalog with automatic connection cleanup."""
        connection = uniclubs_database.get_connection(':memory:')
        self.addCleanup(connection.close)
        uniclubs_database.init_db(connection)
        return connection

    def documents(self, items):
        """Return a matching public overview and sitemap fixture."""
        return source_fixtures.source_page(items), sync_fixtures.sitemap_page(items)

    def first_refresh(self):
        """Generate a valid initial snapshot through the real refresh path."""
        with patch(FETCH_TARGET, return_value=self.documents([self.item])):
            return uniclubs_refresh.refresh_export(self.connection, self.path, now=NOW)

    def test_initial_refresh_writes_a_valid_public_snapshot(self):
        """A first successful run must publish only the validated public catalog document."""
        result = self.first_refresh()
        document = uniclubs_refresh.read_public_export(self.path)
        self.assertEqual(result['events_added'], 1)
        self.assertEqual(len(document['events']), 1)
        self.assertEqual(document['events'][0]['external_id'], 'event-1')
        self.assertNotIn('source_events', result)
        self.assertNotIn('source_clubs', result)

    def test_fresh_runner_restores_ids_before_updating_source_metadata(self):
        """A new machine must retain the previous event ID and original observation time."""
        self.first_refresh()
        before = uniclubs_refresh.read_public_export(self.path)['events'][0]
        fresh = self.catalog()
        changed = source_fixtures.source_event(title='Updated workshop')
        with patch(FETCH_TARGET, return_value=self.documents([changed])):
            result = uniclubs_refresh.refresh_export(fresh, self.path, now=NEXT)
        after = uniclubs_refresh.read_public_export(self.path)['events'][0]
        self.assertEqual(result['events_added'], 0)
        self.assertEqual(result['events_updated'], 1)
        self.assertEqual(after['id'], before['id'])
        self.assertEqual(after['first_seen_utc'], before['first_seen_utc'])
        self.assertEqual(after['title'], 'Updated workshop')

    def test_failed_sync_keeps_the_previous_public_file(self):
        """A network error must not replace a usable snapshot with an empty document."""
        self.first_refresh()
        previous = self.path.read_bytes()
        with patch(FETCH_TARGET, side_effect=ValueError('Unavailable')):
            with self.assertRaises(ValueError):
                uniclubs_refresh.refresh_export(self.connection, self.path, now=NEXT)
        self.assertEqual(self.path.read_bytes(), previous)
        self.assertEqual(len(uniclubs_database.get_events(self.connection)), 1)

    def test_invalid_previous_json_stops_before_network_or_data_changes(self):
        """A damaged saved state must fail instead of silently bootstrapping an empty catalog."""
        self.path.parent.mkdir(parents=True)
        self.path.write_text('{incomplete', encoding='utf-8')
        with patch(FETCH_TARGET) as fetch:
            with self.assertRaises(ValueError):
                uniclubs_refresh.refresh_export(self.connection, self.path, now=NOW)
        fetch.assert_not_called()
        self.assertEqual(self.path.read_text(), '{incomplete')
        self.assertEqual(uniclubs_database.get_events(self.connection), [])

    def test_unsupported_snapshot_version_stops_before_network(self):
        """Incompatible saved data must be reviewed rather than erased and regenerated."""
        self.first_refresh()
        document = json.loads(self.path.read_text())
        document['_meta']['schema_version'] = 999
        self.path.write_text(json.dumps(document), encoding='utf-8')
        with patch(FETCH_TARGET) as fetch:
            with self.assertRaises(ValueError):
                uniclubs_refresh.refresh_export(self.connection, self.path, now=NEXT)
        fetch.assert_not_called()

    def test_file_write_failure_preserves_feed_and_allows_a_later_retry(self):
        """A successfully synced local DB may be newer than its feed after a disk failure."""
        self.first_refresh()
        previous = self.path.read_bytes()
        changed = source_fixtures.source_event(title='New title')
        with patch(FETCH_TARGET, return_value=self.documents([changed])):
            with patch('uniclubs_refresh.uniclubs_export.write_export',
                       side_effect=OSError('Disk')):
                with self.assertRaises(OSError):
                    uniclubs_refresh.refresh_export(self.connection, self.path, now=NEXT)
        self.assertEqual(self.path.read_bytes(), previous)
        self.assertEqual(uniclubs_database.get_events(self.connection)[0]['title'], 'New title')
        with patch(FETCH_TARGET, return_value=self.documents([changed])):
            uniclubs_refresh.refresh_export(self.connection, self.path, now=NEXT)
        self.assertEqual(uniclubs_refresh.read_public_export(self.path)['events'][0]['title'],
                         'New title')

    def test_older_local_catalog_cannot_overwrite_a_newer_public_snapshot(self):
        """Refuse mixing an old local DB with a snapshot from a more recent runner."""
        self.first_refresh()
        with patch(FETCH_TARGET, return_value=self.documents([self.item])):
            uniclubs_refresh.refresh_export(self.connection, self.path, now=NEXT)
        older = self.catalog()
        uniclubs_database.sync_catalog(older, [sync_fixtures.club_record()],
                                       [sync_fixtures.event_record()], now=NOW)
        previous = self.path.read_bytes()
        with patch(FETCH_TARGET) as fetch:
            with self.assertRaises(ValueError):
                uniclubs_refresh.refresh_export(older, self.path, now=NEXT)
        fetch.assert_not_called()
        self.assertEqual(self.path.read_bytes(), previous)

    def test_open_transaction_is_preserved(self):
        """Reject pending caller work without committing or rolling it back."""
        self.connection.execute('''INSERT INTO clubs (external_id, name, source_url)
            VALUES (?, ?, ?)''', ('pending', 'Pending',
                                  'https://uniclubs.ch/hsg/clubs/pending'))
        with self.assertRaises(ValueError):
            uniclubs_refresh.refresh_export(self.connection, self.path, now=NOW)
        self.assertTrue(self.connection.in_transaction)
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 1)

    def test_public_snapshot_size_is_bounded_before_loading(self):
        """Reject excessive files before decoding their JSON payload."""
        self.path.parent.mkdir(parents=True)
        self.path.write_text(' ' * 20, encoding='utf-8')
        with patch.object(config, 'UNICLUBS_MAX_EXPORT_BYTES', 10):
            with self.assertRaises(ValueError):
                uniclubs_refresh.read_public_export(self.path)


if __name__ == '__main__':
    unittest.main()
